import{_ as e,C as g,o as d,c as o,a5 as l,j as a,E as n,a as t}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"Binlog","description":"Redo Log 负责让主库崩溃后能恢复数据，Binlog 负责把这份数据「复制」出去。一个事务提交时，两份日志都要写。问题在于：如果先写 Redo 再写 Binlog，中间断电，主库通过 Redo 恢复了这个事务，Binlog 里却没有——从库会永远少这一笔；反过来先写 Binlog 再写 Redo，主库回滚了，从库却执行了。 这正是两阶段提交要解决的事。","frontmatter":{},"headers":[],"relativePath":"mysql/02-storage-and-logging/chapter-06-binlog.md","filePath":"mysql/02-storage-and-logging/chapter-06-binlog.md"}'),r={name:"mysql/02-storage-and-logging/chapter-06-binlog.md"},h={"data-src-line":"16","data-src-file":"mysql/02-storage-and-logging/chapter-06-binlog.md"},p={"data-src-line":"71","data-src-file":"mysql/02-storage-and-logging/chapter-06-binlog.md"},c={"data-src-line":"75","data-src-file":"mysql/02-storage-and-logging/chapter-06-binlog.md"};function k(y,s,m,b,E,F){const i=g("SvgDiagram");return d(),o("div",null,[s[0]||(s[0]=l('<h1 id="binlog" tabindex="-1" data-src-line="1" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">Binlog <a class="header-anchor" href="#binlog" aria-label="Permalink to &quot;Binlog&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><p data-src-line="3" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">Redo Log 负责让主库崩溃后能恢复数据，Binlog 负责把这份数据「复制」出去。一个事务提交时，两份日志都要写。问题在于：<strong>如果先写 Redo 再写 Binlog，中间断电，主库通过 Redo 恢复了这个事务，Binlog 里却没有——从库会永远少这一笔；反过来先写 Binlog 再写 Redo，主库回滚了，从库却执行了。</strong> 这正是两阶段提交要解决的事。</p></blockquote><h2 id="_1-概述与记录格式" tabindex="-1" data-src-line="5" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">1. 概述与记录格式 <a class="header-anchor" href="#_1-概述与记录格式" aria-label="Permalink to &quot;1. 概述与记录格式&quot;">​</a></h2><h3 id="_1-1-binlog-是什么-用来干什么" tabindex="-1" data-src-line="7" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">1.1 Binlog 是什么，用来干什么 <a class="header-anchor" href="#_1-1-binlog-是什么-用来干什么" aria-label="Permalink to &quot;1.1 Binlog 是什么，用来干什么&quot;">​</a></h3><p data-src-line="9" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">Binlog（Binary Log，二进制日志）是 <strong>MySQL Server 层</strong>产生的日志，与存储引擎无关。它记录的是「数据库做了哪些变更」的逻辑日志，两个用途：</p><ol data-src-line="11" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><li data-src-line="11" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>主从复制</strong>：从库拉取主库的 Binlog，重放这些变更，从而保持数据一致；</li><li data-src-line="12" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>数据恢复</strong>：配合全量备份做时间点恢复（PITR），把数据库恢复到某个历史时刻。</li></ol><p data-src-line="14" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">与 Redo Log 的定位差异见 <a href="./chapter-04-redo-log.html#redo-vs-binlog">Redo Log §5.2</a>，这里先记住一句：<strong>Redo Log 是 InnoDB 的私有账本，管崩溃恢复；Binlog 是 Server 层的公共账本，管复制与恢复。</strong></p>',7)),a("p",h,[n(i,{src:"/mysql/02-storage-and-logging-chapter-06-binlog.svg",alt:"Binlog：事件序列单向追加 + 主从复制数据流"})]),s[1]||(s[1]=l(`<h3 id="_1-2-三种记录格式-同一个事务-三种记法" tabindex="-1" data-src-line="18" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">1.2 三种记录格式：同一个事务，三种记法 <a class="header-anchor" href="#_1-2-三种记录格式-同一个事务-三种记法" aria-label="Permalink to &quot;1.2 三种记录格式：同一个事务，三种记法&quot;">​</a></h3><p data-src-line="20" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">Binlog 可以按三种格式记录同一条 <code>UPDATE</code>：</p><table tabindex="0"><thead data-src-line="22" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><tr data-src-line="22" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><th style="text-align:left;">格式</th><th style="text-align:left;">记录内容</th><th style="text-align:left;">优点</th><th style="text-align:left;">缺点</th></tr></thead><tbody data-src-line="24" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><tr data-src-line="24" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>STATEMENT</code></td><td style="text-align:left;">原始 SQL 语句</td><td style="text-align:left;">日志量小</td><td style="text-align:left;">含 <code>NOW()</code>、<code>RAND()</code>、<code>LIMIT</code> 的语句在从库执行结果可能不同</td></tr><tr data-src-line="25" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>ROW</code></td><td style="text-align:left;">每行变更的前后值</td><td style="text-align:left;">一致性最强，可精确恢复</td><td style="text-align:left;">批量操作时日志量大</td></tr><tr data-src-line="26" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>MIXED</code></td><td style="text-align:left;">默认 <code>STATEMENT</code>，遇不确定语句自动切 <code>ROW</code></td><td style="text-align:left;">折中</td><td style="text-align:left;">仍偶有边界问题</td></tr></tbody></table><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">binlog_format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = ROW</span></span></code></pre></div><p data-src-line="32" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><code>STATEMENT</code> 格式的根本缺陷在于「语句在从库重放时不一定得到相同结果」。典型反例：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 主库执行，NOW() 取主库时间</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- STATEMENT 格式记录的是这条 SQL 本身</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 从库重放时 NOW() 取的是「从库重放那一刻」的时间</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 两边 updated_at 不一致</span></span></code></pre></div><p data-src-line="43" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><code>ROW</code> 格式直接记录变更前后的行值（<code>@1=1</code> 表示第 1 列的值），重放时无歧义——MySQL 8.0 起默认就是 <code>ROW</code>，生产环境也应保持这一选择。代价是日志量随变更行数线性增长。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> binlog_format </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ROW&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ROW 格式下 mysqlbinlog 解码出的内容</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ### UPDATE \`mydb\`.\`users\`</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ###   @1=1                        -- id（BEFORE）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ###   @2=&#39;张三&#39;                   -- name（BEFORE）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ###   @2=&#39;张三三&#39;                 -- name（AFTER）</span></span></code></pre></div><h2 id="_2-两阶段提交" tabindex="-1" data-src-line="55" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">2. 两阶段提交 <a class="header-anchor" href="#_2-两阶段提交" aria-label="Permalink to &quot;2. 两阶段提交&quot;">​</a></h2><h3 id="_2-1-为什么需要两阶段提交" tabindex="-1" data-src-line="57" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">2.1 为什么需要两阶段提交 <a class="header-anchor" href="#_2-1-为什么需要两阶段提交" aria-label="Permalink to &quot;2.1 为什么需要两阶段提交&quot;">​</a></h3><p data-src-line="59" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">这是 Binlog 最核心、也最容易背答案却不理解的问题。先放下结论，从「一份事务要写两份日志」这个事实出发推导。</p><p data-src-line="61" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">一次 <code>COMMIT</code>，InnoDB 要写 Redo Log（保证崩溃恢复），Server 层要写 Binlog（保证复制）。两份日志必须<strong>同时都写成功</strong>，这个事务才算真正提交。但磁盘写入有先后，任何「先后顺序」都会在中间断电时产生不一致：</p><p data-src-line="63" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>方案一：先写 Redo，再写 Binlog</strong></p><p data-src-line="65" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">崩溃后主库用 Redo Log 恢复，这个事务<strong>生效了</strong>。但 Binlog 里没有这条记录，从库重放时<strong>少了这笔</strong>。主库有、从库无 → 主从不一致。</p><p data-src-line="67" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>方案二：先写 Binlog，再写 Redo</strong></p><p data-src-line="69" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">崩溃后主库用 Redo Log 恢复，这个事务<strong>没生效</strong>（被回滚）。但 Binlog 里已经写了，从库重放时<strong>多了这笔</strong>。主库无、从库有 → 主从不一致。</p>`,16)),a("p",p,[n(i,{src:"/mysql/02-storage-and-logging-chapter-06-2pc-failures.svg",alt:"固定顺序的失败：断电发生在两份日志之间，主从总会差一笔"})]),s[2]||(s[2]=a("p",{"data-src-line":"73","data-src-file":"mysql/02-storage-and-logging/chapter-06-binlog.md"},[t("无论哪种固定顺序，断电都会打破「主库和从库看到同一批已提交事务」的约定。两阶段提交的解法，是把这个「提交」拆成两段，并在崩溃恢复时"),a("strong",null,"根据 Binlog 的状态反推该不该提交"),t("：")],-1)),a("p",c,[n(i,{src:"/mysql/02-storage-and-logging-chapter-06-2pc.svg",alt:"两阶段提交：prepare → 写 Binlog → commit，恢复时用 Binlog 裁决"})]),s[3]||(s[3]=l(`<p data-src-line="77" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>核心在于：Binlog 的写入是「分水岭」。</strong> Binlog 写成功之前，主库和从库都不该有这个事务；Binlog 写成功之后，主库必须提交，才能和已经（或将要）重放这条 Binlog 的从库保持一致。Redo Log 的 prepare 状态，就是「先占个位，等 Binlog 的结果再定去留」。</p><div class="info custom-block"><p class="custom-block-title">怎么「在 Binlog 里找对应记录」</p><p data-src-line="80" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">崩溃恢复时，InnoDB 用 Redo Log prepare 记录里携带的 <strong>XID</strong>（事务唯一标识）去 Binlog 里匹配同名 XID 事件。XID 事件是 <code>ROW</code> 格式下事务提交时写入的标记，两者 XID 相同即认为「这个事务的 Binlog 已完整落盘」。</p></div><p data-src-line="83" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">两阶段提交的失败背景与一致性推导，<a href="./chapter-04-redo-log.html#two-phase-commit">Redo Log §5.1</a> 从崩溃恢复侧给出了同一套结论。</p><h2 id="_3-查看与解析" tabindex="-1" data-src-line="85" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">3. 查看与解析 <a class="header-anchor" href="#_3-查看与解析" aria-label="Permalink to &quot;3. 查看与解析&quot;">​</a></h2><h3 id="_3-1-查看与解析-binlog" tabindex="-1" data-src-line="87" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">3.1 查看与解析 Binlog <a class="header-anchor" href="#_3-1-查看与解析-binlog" aria-label="Permalink to &quot;3.1 查看与解析 Binlog&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看 Binlog 文件列表</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BINARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOGS;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看当前正在写入的 Binlog 及位置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MASTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> STATUS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看某个文件里的事件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW BINLOG EVENTS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;binlog.000001&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p data-src-line="100" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">用 <code>mysqlbinlog</code> 工具把二进制内容解码成可读文本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqlbinlog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base64-output=DECODE-ROWS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binlog.000001</span></span></code></pre></div><p data-src-line="106" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><code>-v</code> 会把 ROW 格式的行变更还原成 <code>### @1=...</code> 形式；写成 <code>-vv</code> 则会附带字段类型等更多信息。</p><h3 id="_3-2-binlog-事件类型" tabindex="-1" data-src-line="108" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">3.2 Binlog 事件类型 <a class="header-anchor" href="#_3-2-binlog-事件类型" aria-label="Permalink to &quot;3.2 Binlog 事件类型&quot;">​</a></h3><p data-src-line="110" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">一个 Binlog 文件由一系列事件（Event）顺序组成。常见事件：</p><table tabindex="0"><thead data-src-line="112" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><tr data-src-line="112" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><th style="text-align:left;">事件类型</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="114" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><tr data-src-line="114" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>FORMAT_DESCRIPTION</code></td><td style="text-align:left;">文件头，描述 Binlog 版本</td></tr><tr data-src-line="115" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>QUERY</code></td><td style="text-align:left;">SQL 语句事件（STATEMENT 格式）</td></tr><tr data-src-line="116" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>TABLE_MAP</code></td><td style="text-align:left;">表结构映射（ROW 格式下先声明表）</td></tr><tr data-src-line="117" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>WRITE_ROWS</code> / <code>UPDATE_ROWS</code> / <code>DELETE_ROWS</code></td><td style="text-align:left;">行级写入 / 更新 / 删除（ROW 格式）</td></tr><tr data-src-line="118" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>XID</code></td><td style="text-align:left;">事务提交标记（两阶段提交的「分水岭」）</td></tr><tr data-src-line="119" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><td style="text-align:left;"><code>ROTATE</code></td><td style="text-align:left;">文件轮转，切到下一个 Binlog 文件</td></tr></tbody></table><h2 id="_4-管理与恢复" tabindex="-1" data-src-line="121" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">4. 管理与恢复 <a class="header-anchor" href="#_4-管理与恢复" aria-label="Permalink to &quot;4. 管理与恢复&quot;">​</a></h2><h3 id="_4-1-binlog-管理与清理" tabindex="-1" data-src-line="123" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">4.1 Binlog 管理与清理 <a class="header-anchor" href="#_4-1-binlog-管理与清理" aria-label="Permalink to &quot;4.1 Binlog 管理与清理&quot;">​</a></h3><p data-src-line="125" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">Binlog 只会追加、不会复用，需要主动清理，否则会写满磁盘。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看当前写入的 Binlog 及位置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MASTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> STATUS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 手动切换文件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FLUSH LOGS;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 清理指定日期之前的 Binlog</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PURGE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BINARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOGS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEFORE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;2024-01-01 00:00:00&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 清理指定文件之前的 Binlog（含该文件）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PURGE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BINARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOGS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;binlog.000010&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 设置自动过期时间（秒）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> binlog_expire_logs_seconds </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 604800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 7 天</span></span></code></pre></div><h3 id="_4-2-基于-binlog-的时间点恢复-pitr" tabindex="-1" data-src-line="144" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">4.2 基于 Binlog 的时间点恢复（PITR） <a class="header-anchor" href="#_4-2-基于-binlog-的时间点恢复-pitr" aria-label="Permalink to &quot;4.2 基于 Binlog 的时间点恢复（PITR）&quot;">​</a></h3><p data-src-line="146" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">误删数据后，用「全量备份 + Binlog 重放」把数据恢复到指定时刻。常见有两种切法：恢复到误操作前一刻，或者跳过误操作、从它之后继续：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 先恢复最近一次全量备份</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full_backup.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 定位误操作发生在哪个 Binlog、哪个时间</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqlbinlog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base64-output=DECODE-ROWS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binlog.000005</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;DELETE FROM users&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 恢复到误操作前一刻（不含误操作）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqlbinlog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stop-datetime=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2024-01-01 12:30:00&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    binlog.000001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binlog.000002</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binlog.000003</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 跳过误操作，从误操作之后继续恢复</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqlbinlog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --start-datetime=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2024-01-01 12:31:00&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    binlog.000003</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binlog.000004</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binlog.000005</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span></code></pre></div><p data-src-line="164" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">恢复依赖的是 Binlog 的<strong>有序性与完整性</strong>，这也是为什么生产上要 <code>sync_binlog=1</code>（每次提交都刷盘）保证 Binlog 不丢。</p><h2 id="_5-最佳实践" tabindex="-1" data-src-line="166" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md">5. 最佳实践 <a class="header-anchor" href="#_5-最佳实践" aria-label="Permalink to &quot;5. 最佳实践&quot;">​</a></h2><ol data-src-line="168" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><li data-src-line="168" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>用 <code>ROW</code> 格式</strong>：一致性最强，便于精确恢复与排查。</li><li data-src-line="169" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>开启 <code>sync_binlog=1</code></strong>：与 <code>innodb_flush_log_at_trx_commit=1</code> 配合构成「双 1」，崩溃时数据与 Binlog 都不丢。</li><li data-src-line="170" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>设过期时间并监控磁盘</strong>：Binlog 只增不减，不清理会写满磁盘。</li><li data-src-line="171" data-src-file="mysql/02-storage-and-logging/chapter-06-binlog.md"><strong>不要在线禁用 Binlog</strong>：会同时断掉复制与 PITR 能力。</li></ol>`,22))])}const q=e(r,[["render",k]]);export{f as __pageData,q as default};
